test('invoiceTotals VAT with discount reduces VAT base', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 20 }],
  };
  const totals = invoiceTotals(invoice);
  const vatBase = 10000 - 2000;
  const vat = Math.round(vatBase * 21 / 100);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 10000 - 2000 + vat);
});

